sys_security_acl.script:
if (gs.hasRole('x_2316161_bjit_e_0.hr_admin') || gs.hasRole('x_2316161_bjit_e_0.executive') || gs.hasRole('x_2316161_bjit_e_0.erp_admin')) {
    answer = true;
} else if (gs.hasRole('x_2316161_bjit_e_0.manager')) {
    var empGr = new GlideRecord('x_2316161_bjit_e_0_emp');
    if (empGr.get(current.getValue('employee'))) {
        var userGr = new GlideRecord('sys_user');
        if (userGr.get(empGr.getValue('user'))) {
            answer = userGr.getValue('manager') == gs.getUserID();
        }
    }
} else {
    answer = current.employee.user == gs.getUserID();
}
